#if UNITY_EDITOR
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;

namespace DrawDecks.Client.Editor
{
    /// <summary>
    /// Creates a launchable empty scene and registers it for player builds.
    /// The runtime UI is generated by DrawDecksGame at startup.
    /// </summary>
    [InitializeOnLoad]
    internal static class DrawDecksEditorBootstrap
    {
        private const string MainScenePath = "Assets/Scenes/Main.unity";

        static DrawDecksEditorBootstrap()
        {
            EditorApplication.delayCall += EnsureMainScene;
        }

        private static void EnsureMainScene()
        {
            if (EditorApplication.isPlayingOrWillChangePlaymode)
                return;

            string absolutePath = Path.GetFullPath(Path.Combine(UnityEngine.Application.dataPath, "../" + MainScenePath));
            string directory = Path.GetDirectoryName(absolutePath);
            if (!Directory.Exists(directory))
                Directory.CreateDirectory(directory);

            if (!File.Exists(absolutePath))
            {
                Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
                EditorSceneManager.SaveScene(scene, MainScenePath);
                AssetDatabase.Refresh();
            }

            var scenes = EditorBuildSettings.scenes.ToList();
            if (!scenes.Any(scene => scene.path == MainScenePath))
            {
                scenes.Insert(0, new EditorBuildSettingsScene(MainScenePath, true));
                EditorBuildSettings.scenes = scenes.ToArray();
            }
        }
    }
}
#endif
